    45→## Options Considered
    46→
    47→### Option A: VS Code API (Recommended)
    48→
    49→```typescript
    50→// Insert into active text editor
    51→async function insertIntoEditor(text: string): Promise<void> {
    52→    const editor = vscode.window.activeTextEditor;
    53→    if (!editor) return;
    54→
    55→    await editor.edit(editBuilder => {
    56→        editBuilder.insert(editor.selection.active, text);
    57→    });
    58→}
    59→
    60→// Insert into active terminal
    61→function insertIntoTerminal(text: string, execute: boolean = false): void {
    62→    const terminal = vscode.window.activeTerminal;
    63→    if (!terminal) return;
    64→
    65→    terminal.sendText(text, execute);  // execute=true adds Enter
    66→}
    67→
    68→// Insert into input box (Command Palette, etc.)
    69→async function insertIntoInputBox(text: string): Promise<void> {
    70→    // VS Code doesn't have direct API for this
    71→    // Use clipboard workaround
    72→    await vscode.env.clipboard.writeText(text);
    73→    await vscode.commands.executeCommand('editor.action.clipboardPasteAction');
    74→}
