   211→### Streaming Text Insertion
   212→
   213→For real-time transcription display with interim result rewriting.
   214→
   215→## Interim Text Replacement for Streaming Dictation
   216→
   217→The key challenge is replacing text atomically as interim results arrive with corrections. This section details the mechanics.
   218→
   219→### Visual Mechanics
   220→
   221→```
   222→┌─────────────────────────────────────────────────────────────────────────────┐
   223→│                    TEXT REPLACEMENT MECHANICS                                │
   224→├─────────────────────────────────────────────────────────────────────────────┤
   225→│                                                                              │
   226→│  Editor state before dictation:                                             │
   227→│  ┌──────────────────────────────────────────────────────────────────────┐   │
   228→│  │  const user = await getUser(|                                        │   │
   229→│  └──────────────────────────────────────────────────────────────────────┘   │
   230→│                                  ↑ cursor = anchor (fixed reference point)  │
   231→│                                                                              │
   232→│  Interim 1: "I need an analyst"                                             │
   233→│  ┌──────────────────────────────────────────────────────────────────────┐   │
   234→│  │  const user = await getUser(I need an analyst|                       │   │
   235→│  └──────────────────────────────────────────────────────────────────────┘   │
   236→│                                 ├───────────────┤ interim region (gray)     │
   237→│                                 anchor          anchor + interimLength      │
   238→│                                                                              │
   239→│  Interim 2: "I need analytics" (CORRECTION - "analyst" → "analytics")       │
   240→│  Action: Replace range [anchor, anchor+17] with new text                    │
   241→│  ┌──────────────────────────────────────────────────────────────────────┐   │
   242→│  │  const user = await getUser(I need analytics|                        │   │
   243→│  └──────────────────────────────────────────────────────────────────────┘   │
   244→│                                 ├─────────────┤ new interim region          │
   245→│                                                                              │
   246→│  LLM Cleanup streams: "Add analytics"                                       │
   247→│  Action: Replace interim region with cleaned text (no longer gray)          │
   248→│  ┌──────────────────────────────────────────────────────────────────────┐   │
   249→│  │  const user = await getUser(Add analytics|                           │   │
   250→│  └──────────────────────────────────────────────────────────────────────┘   │
   251→│                                 ├───────────┤ final text (normal style)     │
   252→│                                                                              │
   253→└─────────────────────────────────────────────────────────────────────────────┘
   254→```
   255→
   256→### InterimTextManager Implementation
   257→
   258→```typescript
   259→/**
   260→ * Manages interim text display with rewriting support.
   261→ *
   262→ * Key concepts:
   263→ * - anchor: Fixed position where dictation started (never moves)
   264→ * - interimLength: Current length of interim text (for calculating replacement range)
   265→ * - Atomic replacement: Uses editBuilder.replace() for flicker-free updates
   266→ * - Undo grouping: All interim edits are one undo operation
   267→ */
   268→class InterimTextManager {
   269→    // Fixed starting point - never moves during dictation
   270→    private anchor: vscode.Position | null = null;
   271→
   272→    // Current interim text length for calculating replacement range
   273→    private interimLength = 0;
   274→
   275→    // Decoration for gray/italic interim styling
   276→    private interimStyle = vscode.window.createTextEditorDecorationType({
   277→        color: new vscode.ThemeColor('editorGhostText.foreground'),
   278→        fontStyle: 'italic',
   279→        // Optional: add subtle background
   280→        backgroundColor: new vscode.ThemeColor('editor.wordHighlightBackground'),
   281→    });
   282→
   283→    /**
   284→     * Handle an interim result from the server.
   285→     * Replaces all existing interim text with new text.
   286→     */
   287→    async handleInterim(
   288→        editor: vscode.TextEditor,
   289→        text: string,
   290→        isFinal: boolean
   291→    ): Promise<void> {
   292→        // First interim: record anchor position
   293→        if (!this.anchor) {
   294→            this.anchor = editor.selection.active;
   295→        }
   296→
   297→        // Calculate the range of existing interim text
   298→        const interimStart = this.anchor;
   299→        const interimEnd = this.anchor.translate(0, this.interimLength);
   300→        const interimRange = new vscode.Range(interimStart, interimEnd);
   301→
   302→        // Atomic edit: replace entire interim region with new text
   303→        const success = await editor.edit(editBuilder => {
   304→            if (this.interimLength > 0) {
   305→                // Replace existing interim text
   306→                editBuilder.replace(interimRange, text);
   307→            } else {
   308→                // First insertion
   309→                editBuilder.insert(this.anchor!, text);
   310→            }
   311→        }, {
   312→            // Undo grouping: don't create undo stops between interim edits
   313→            undoStopBefore: false,
   314→            undoStopAfter: false,
   315→        });
   316→
   317→        if (!success) {
   318→            console.warn('InterimTextManager: edit failed');
   319→            return;
   320→        }
   321→
   322→        // Update tracked length
   323→        this.interimLength = text.length;
   324→
   325→        // Apply or remove interim styling
   326→        if (!isFinal) {
   327→            const newRange = new vscode.Range(
   328→                this.anchor,
   329→                this.anchor.translate(0, this.interimLength)
   330→            );
   331→            editor.setDecorations(this.interimStyle, [newRange]);
   332→        } else {
   333→            // Final STT result: remove interim styling
   334→            editor.setDecorations(this.interimStyle, []);
   335→        }
   336→
   337→        // Move cursor to end of inserted text
   338→        const newCursorPos = this.anchor.translate(0, this.interimLength);
   339→        editor.selection = new vscode.Selection(newCursorPos, newCursorPos);
   340→    }
   341→
   342→    /**
   343→     * Handle streaming LLM cleanup tokens.
   344→     * First token replaces interim text; subsequent tokens append.
   345→     */
   346→    async handleStreamingToken(
   347→        editor: vscode.TextEditor,
   348→        token: string,
   349→        position: number  // Character position in the cleaned output
   350→    ): Promise<void> {
   351→        if (!this.anchor) return;
   352→
   353→        // Clear interim styling on first token
   354→        if (position === 0) {
   355→            editor.setDecorations(this.interimStyle, []);
   356→        }
   357→
   358→        if (position === 0 && this.interimLength > 0) {
   359→            // First token: replace entire interim text
   360→            const interimRange = new vscode.Range(
   361→                this.anchor,
   362→                this.anchor.translate(0, this.interimLength)
   363→            );
   364→            await editor.edit(eb => eb.replace(interimRange, token), {
   365→                undoStopBefore: false,
   366→                undoStopAfter: false,
   367→            });
   368→            this.interimLength = token.length;
   369→        } else {
   370→            // Subsequent tokens: append
   371→            const insertPos = this.anchor.translate(0, this.interimLength);
   372→            await editor.edit(eb => eb.insert(insertPos, token), {
   373→                undoStopBefore: false,
   374→                undoStopAfter: false,
   375→            });
   376→            this.interimLength += token.length;
   377→        }
   378→
   379→        // Move cursor to end
   380→        const newCursorPos = this.anchor.translate(0, this.interimLength);
   381→        editor.selection = new vscode.Selection(newCursorPos, newCursorPos);
   382→    }
   383→
   384→    /**
   385→     * Finalize the dictation session.
   386→     * Creates undo stop so entire dictation is one undo operation.
   387→     */
   388→    async finalize(editor: vscode.TextEditor): Promise<void> {
   389→        if (!this.anchor) return;
   390→
   391→        // Create final undo stop - entire dictation is now one undo
   392→        await editor.edit(() => {}, {
   393→            undoStopBefore: false,
   394→            undoStopAfter: true,  // End the undo group
   395→        });
   396→
   397→        // Clear styling
   398→        editor.setDecorations(this.interimStyle, []);
   399→
   400→        // Reset state
   401→        this.reset();
   402→    }
   403→
   404→    /**
   405→     * Cancel dictation and remove any interim text.
   406→     */
   407→    async cancel(editor: vscode.TextEditor): Promise<void> {
   408→        if (!this.anchor || this.interimLength === 0) {
   409→            this.reset();
   410→            return;
   411→        }
   412→
   413→        // Delete the interim text
   414→        const interimRange = new vscode.Range(
   415→            this.anchor,
   416→            this.anchor.translate(0, this.interimLength)
   417→        );
   418→        await editor.edit(eb => eb.delete(interimRange));
   419→
   420→        // Clear styling and reset
   421→        editor.setDecorations(this.interimStyle, []);
   422→        this.reset();
   423→    }
   424→
   425→    reset(): void {
   426→        this.anchor = null;
   427→        this.interimLength = 0;
   428→    }
   429→
   430→    isActive(): boolean {
   431→        return this.anchor !== null;
   432→    }
   433→}
   434→```
   435→
   436→### Multi-Line Interim Text
   437→
   438→For interim text that spans multiple lines, use offset-based positioning:
   439→
   440→```typescript
   441→class MultiLineInterimManager extends InterimTextManager {
   442→    private anchorOffset: number = 0;
   443→
   444→    async handleInterim(
   445→        editor: vscode.TextEditor,
   446→        text: string,
   447→        isFinal: boolean
   448→    ): Promise<void> {
   449→        const document = editor.document;
   450→
   451→        if (this.anchorOffset === 0) {
   452→            // Record offset (character position from start of document)
   453→            this.anchorOffset = document.offsetAt(editor.selection.active);
   454→        }
   455→
   456→        // Calculate positions from offsets (handles multi-line correctly)
   457→        const startPos = document.positionAt(this.anchorOffset);
   458→        const endPos = document.positionAt(this.anchorOffset + this.interimLength);
   459→        const interimRange = new vscode.Range(startPos, endPos);
   460→
   461→        await editor.edit(editBuilder => {
   462→            if (this.interimLength > 0) {
   463→                editBuilder.replace(interimRange, text);
   464→            } else {
   465→                editBuilder.insert(startPos, text);
   466→            }
   467→        }, {
   468→            undoStopBefore: false,
   469→            undoStopAfter: false,
   470→        });
   471→
   472→        this.interimLength = text.length;
   473→
   474→        // Apply styling to multi-line range
   475→        if (!isFinal) {
   476→            const newEndPos = document.positionAt(this.anchorOffset + this.interimLength);
   477→            const newRange = new vscode.Range(startPos, newEndPos);
   478→            editor.setDecorations(this.interimStyle, [newRange]);
   479→        }
   480→    }
   481→}
   482→```
   483→
   484→### Terminal Handling (No Interim Display)
   485→
   486→Terminals don't support interim display - too disruptive. Only stream final cleaned tokens:
   487→
   488→```typescript
   489→class TerminalInserter {
   490→    /**
   491→     * Terminals receive only final cleaned tokens - no interim display.
   492→     * Interim results are ignored since terminal text can't be "replaced".
   493→     */
   494→    handleMessage(terminal: vscode.Terminal, msg: ServerMessage): void {
   495→        switch (msg.type) {
   496→            case 'interim':
   497→                // Ignore - terminals can't replace text
   498→                break;
   499→
   500→            case 'streaming':
   501→                // Stream each cleaned token directly
   502→                terminal.sendText(msg.token, false);
   503→                break;
   504→
   505→            case 'final':
   506→                // Execute voice commands
   507→                for (const cmd of msg.commands) {
   508→                    this.executeCommand(terminal, cmd);
   509→                }
   510→                break;
   511→        }
   512→    }
   513→
   514→    private executeCommand(terminal: vscode.Terminal, cmd: VoiceCommand): void {
   515→        switch (cmd.action) {
   516→            case 'enter':
   517→                terminal.sendText('', true);  // Send newline
   518→                break;
   519→            case 'tab':
   520→                terminal.sendText('\t', false);
   521→                break;
   522→            case 'clear':
   523→                terminal.sendText('\u0015', false);  // Ctrl+U
   524→                break;
   525→        }
   526→    }
   527→}
   528→```
   529→
   530→### Edge Cases
   531→
   532→| Edge Case | Handling |
   533→|-----------|----------|
   534→| User types during dictation | Anchor stays fixed; interim region is tracked separately |
   535→| Rapid interim updates | Each `edit()` is atomic; VS Code queues them in order |
   536→| Editor loses focus | Continue tracking; apply when focus returns |
   537→| User clicks elsewhere | Cancel dictation via `cancel()` method |
   538→| Undo during dictation | Entire dictation undone as single operation |
   539→| Multi-cursor mode | Not supported; use primary cursor only |
   540→| Read-only editor | Show error via status bar, don't insert |
