   608→function processSpecialTokens(text: string): string {
   609→    // Handle spoken punctuation
   610→    const replacements: Record<string, string> = {
   611→        ' period ': '. ',
   612→        ' comma ': ', ',
   613→        ' question mark ': '? ',
   614→        ' exclamation point ': '! ',
   615→        ' colon ': ': ',
   616→        ' semicolon ': '; ',
   617→        ' new line ': '\n',
   618→        ' new paragraph ': '\n\n',
   619→        ' tab ': '\t',
   620→        ' open paren ': '(',
   621→        ' close paren ': ')',
   622→        ' open bracket ': '[',
   623→        ' close bracket ': ']',
   624→        ' open brace ': '{',
   625→        ' close brace ': '}',
   626→    };
   627→
   628→    let processed = text.toLowerCase();
   629→    for (const [spoken, char] of Object.entries(replacements)) {
   630→        processed = processed.replace(new RegExp(spoken, 'gi'), char);
   631→    }
   632→
   633→    return processed;
   634→}
