   637→### Editor Context Preservation
   638→
   639→```typescript
   640→async function insertWithContext(text: string): Promise<void> {
   641→    const editor = vscode.window.activeTextEditor;
   642→    if (!editor) return;
   643→
   644→    // Detect indentation at current line
   645→    const line = editor.document.lineAt(editor.selection.active.line);
   646→    const indent = line.text.match(/^\s*/)?.[0] || '';
   647→
   648→    // Apply indentation to multi-line text
   649→    const indentedText = text
   650→        .split('\n')
   651→        .map((line, i) => i === 0 ? line : indent + line)
   652→        .join('\n');
   653→
   654→    await editor.edit(editBuilder => {
   655→        editBuilder.insert(editor.selection.active, indentedText);
   656→    });
   657→}
