/**
 * VTThought Voice Commands (ADR-008)
 *
 * Parses and executes voice commands from transcriptions.
 * Implements keyword-based command detection.
 */

import * as vscode from 'vscode';

/**
 * Voice command definition.
 */
export interface VoiceCommand {
    trigger: string[];           // Phrases that trigger this command
    action: string;              // VS Code command to execute
    params?: (match: string) => Record<string, unknown> | null;  // Extract parameters
    terminal?: boolean;          // Is this a terminal command?
}

/**
 * Parsed transcription result.
 */
export interface ParsedTranscription {
    text: string;              // Text to insert (with commands removed)
    commands: Command[];       // Commands to execute
    hasTrailingCommand: boolean;  // Ends with a command
}

/**
 * Parsed command ready for execution.
 */
export interface Command {
    action: string;
    params?: Record<string, unknown>;
    terminal?: boolean;
}

/**
 * Voice command registry.
 * Based on ADR-008 command categories.
 */
const VOICE_COMMANDS: VoiceCommand[] = [
    // Execution Commands (Terminal/Claude Code)
    {
        trigger: ['enter', 'send', 'submit', 'run that', 'execute'],
        action: 'terminal.send-enter',
        terminal: true
    },
    {
        trigger: ['cancel', 'stop that', 'abort'],
        action: 'terminal.send-ctrl-c',
        terminal: true
    },

    // Editing Commands
    {
        trigger: ['delete that', 'undo', 'scratch that'],
        action: 'undo'
    },
    {
        trigger: ['clear line', 'delete line'],
        action: 'editor.action.deleteLines'
    },
    {
        trigger: ['select all'],
        action: 'editor.action.selectAll'
    },
    {
        trigger: ['new line', 'newline'],
        action: 'type',
        params: () => ({ text: '\n' })
    },
    {
        trigger: ['tab'],
        action: 'type',
        params: () => ({ text: '\t' })
    },

    // Navigation Commands
    {
        trigger: ['go to line'],
        action: 'workbench.action.gotoLine',
        params: (match) => {
            const num = match.match(/go to line (\d+)/i)?.[1];
            return num ? { lineNumber: parseInt(num) } : null;
        }
    },

    // VS Code Commands
    {
        trigger: ['save file', 'save'],
        action: 'workbench.action.files.save'
    },
    {
        trigger: ['close file', 'close tab'],
        action: 'workbench.action.closeActiveEditor'
    },
    {
        trigger: ['open terminal', 'show terminal'],
        action: 'workbench.action.terminal.toggleTerminal'
    },
    {
        trigger: ['command palette'],
        action: 'workbench.action.showCommands'
    },

    // Dictation Control
    {
        trigger: ['stop listening', 'pause'],
        action: 'voicecode.stopListening'
    }
];

/**
 * Parses voice commands from transcription.
 * Implements keyword-based command detection from ADR-008.
 */
export class CommandParser {
    private commands: VoiceCommand[];

    constructor(commands: VoiceCommand[] = VOICE_COMMANDS) {
        this.commands = commands;
    }

    parse(transcription: string): ParsedTranscription {
        let text = transcription;
        const foundCommands: Command[] = [];

        // Check for commands at the end of transcription
        for (const cmd of this.commands) {
            for (const trigger of cmd.trigger) {
                const regex = new RegExp(`\\s*${this.escapeRegex(trigger)}\\s*$`, 'i');
                if (regex.test(text)) {
                    text = text.replace(regex, '').trim();
                    foundCommands.push({
                        action: cmd.action,
                        params: cmd.params?.(transcription) ?? undefined,
                        terminal: cmd.terminal
                    });
                }
            }
        }

        return {
            text,
            commands: foundCommands.reverse(),  // Execute in order spoken
            hasTrailingCommand: foundCommands.length > 0
        };
    }

    private escapeRegex(str: string): string {
        return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    }
}

/**
 * Executes parsed voice commands.
 */
export class CommandExecutor {
    async execute(command: Command): Promise<void> {
        if (command.terminal) {
            await this.executeTerminalCommand(command);
        } else {
            await vscode.commands.executeCommand(
                command.action,
                command.params
            );
        }
    }

    private async executeTerminalCommand(command: Command): Promise<void> {
        const terminal = vscode.window.activeTerminal;
        if (!terminal) {
            vscode.window.showWarningMessage('No active terminal for command');
            return;
        }

        switch (command.action) {
            case 'terminal.send-enter':
                terminal.sendText('', true);  // Empty string with execute=true
                break;
            case 'terminal.send-ctrl-c':
                terminal.sendText('\x03', false);
                break;
            case 'terminal.clear-line':
                terminal.sendText('\u0015', false);  // Ctrl+U
                break;
            default:
                vscode.window.showWarningMessage(`Unknown terminal command: ${command.action}`);
        }
    }
}

/**
 * Disambiguation for homophones (similar-sounding words).
 * From ADR-008.
 */
const HOMOPHONES: Record<string, string[]> = {
    'enter': ['inter', 'inner'],
    'send': ['sent', 'scent'],
    'delete': ['the lead', 'dilute'],
    'undo': ['un do', 'and do']
};

/**
 * Normalize text by applying homophone corrections.
 */
export function normalizeCommand(text: string): string {
    let normalized = text.toLowerCase();
    for (const [correct, variants] of Object.entries(HOMOPHONES)) {
        for (const variant of variants) {
            normalized = normalized.replace(variant, correct);
        }
    }
    return normalized;
}

/**
 * Process transcription and execute commands.
 * Full pipeline from ADR-008.
 */
export async function processTranscription(rawText: string): Promise<void> {
    const parser = new CommandParser();
    const executor = new CommandExecutor();

    // Parse commands
    const parsed = parser.parse(rawText);

    // Insert text (if any)
    if (parsed.text) {
        await insertText(parsed.text);
    }

    // Execute commands
    for (const cmd of parsed.commands) {
        await executor.execute(cmd);
    }
}

/**
 * Insert text at cursor position.
 */
async function insertText(text: string): Promise<void> {
    const editor = vscode.window.activeTextEditor;
    if (!editor) return;

    await editor.edit(editBuilder => {
        editBuilder.insert(editor.selection.active, text);
    });
}

// Export default parser instance
export const commandParser = new CommandParser();
export const commandExecutor = new CommandExecutor();

/**
 * VTThought Text Insertion (ADR-007)
 *
 * Manages text insertion into VS Code editor and terminal.
 * Implements interim text display with atomic rewriting.
 */

import * as vscode from 'vscode';

/**
 * Server message types from backend WebSocket.
 */
export type ServerMessage =
    | { type: 'interim'; text: string; is_final: boolean; confidence: number; changes: TextChange[] }
    | { type: 'streaming'; token: string; position: number }
    | { type: 'final'; raw: string; cleaned: string; commands: VoiceCommand[] }
    | { type: 'error'; code: string; message: string };

/**
 * Text edit operation for interim updates.
 */
export interface TextChange {
    start: number;
    deleteCount: number;
    insert: string;
}

/**
 * Voice command to execute.
 */
export interface VoiceCommand {
    action: string;
    params?: Record<string, unknown>;
    terminal?: boolean;
}

/**
 * Manages interim text display with rewriting support.
 *
 * Key concepts:
 * - anchor: Fixed position where dictation started (never moves)
 * - interimLength: Current length of interim text (for calculating replacement range)
 * - Atomic replacement: Uses editBuilder.replace() for flicker-free updates
 * - Undo grouping: All interim edits are one undo operation
 *
 * Implements the interim text manager from ADR-007.
 */
export class InterimTextManager {
    // Fixed starting point - never moves during dictation
    private anchor: vscode.Position | null = null;

    // Current interim text length for calculating replacement range
    private interimLength = 0;

    // Decoration for gray/italic interim styling
    private readonly interimStyle: vscode.TextEditorDecorationType;

    constructor() {
        this.interimStyle = vscode.window.createTextEditorDecorationType({
            color: new vscode.ThemeColor('editorGhostText.foreground'),
            fontStyle: 'italic',
            // Optional: add subtle background
            backgroundColor: new vscode.ThemeColor('editor.wordHighlightBackground'),
        });
    }

    /**
     * Handle an interim result from the server.
     * Replaces all existing interim text with new text.
     */
    async handleInterim(
        editor: vscode.TextEditor,
        text: string,
        isFinal: boolean
    ): Promise<void> {
        // First interim: record anchor position
        if (!this.anchor) {
            this.anchor = editor.selection.active;
        }

        // Calculate the range of existing interim text
        const interimStart = this.anchor;
        const interimEnd = this.anchor.translate(0, this.interimLength);
        const interimRange = new vscode.Range(interimStart, interimEnd);

        // Atomic edit: replace entire interim region with new text
        const success = await editor.edit(editBuilder => {
            if (this.interimLength > 0) {
                // Replace existing interim text
                editBuilder.replace(interimRange, text);
            } else {
                // First insertion
                editBuilder.insert(this.anchor!, text);
            }
        }, {
            // Undo grouping: don't create undo stops between interim edits
            undoStopBefore: false,
            undoStopAfter: false,
        });

        if (!success) {
            console.warn('InterimTextManager: edit failed');
            return;
        }

        // Update tracked length
        this.interimLength = text.length;

        // Apply or remove interim styling
        if (!isFinal) {
            const newRange = new vscode.Range(
                this.anchor,
                this.anchor.translate(0, this.interimLength)
            );
            editor.setDecorations(this.interimStyle, [newRange]);
        } else {
            // Final STT result: remove interim styling
            editor.setDecorations(this.interimStyle, []);
        }

        // Move cursor to end of inserted text
        const newCursorPos = this.anchor.translate(0, this.interimLength);
        editor.selection = new vscode.Selection(newCursorPos, newCursorPos);
    }

    /**
     * Handle streaming LLM cleanup tokens.
     * First token replaces interim text; subsequent tokens append.
     */
    async handleStreamingToken(
        editor: vscode.TextEditor,
        token: string,
        position: number  // Character position in the cleaned output
    ): Promise<void> {
        if (!this.anchor) {
            return;
        }

        // Clear interim styling on first token
        if (position === 0) {
            editor.setDecorations(this.interimStyle, []);
        }

        if (position === 0 && this.interimLength > 0) {
            // First token: replace entire interim text
            const interimRange = new vscode.Range(
                this.anchor,
                this.anchor.translate(0, this.interimLength)
            );
            await editor.edit(eb => eb.replace(interimRange, token), {
                undoStopBefore: false,
                undoStopAfter: false,
            });
            this.interimLength = token.length;
        } else {
            // Subsequent tokens: append
            const insertPos = this.anchor.translate(0, this.interimLength);
            await editor.edit(eb => eb.insert(insertPos, token), {
                undoStopBefore: false,
                undoStopAfter: false,
            });
            this.interimLength += token.length;
        }

        // Move cursor to end
        const newCursorPos = this.anchor.translate(0, this.interimLength);
        editor.selection = new vscode.Selection(newCursorPos, newCursorPos);
    }

    /**
     * Finalize the dictation session.
     * Creates undo stop so entire dictation is one undo operation.
     */
    async finalize(editor: vscode.TextEditor): Promise<void> {
        if (!this.anchor) {
            return;
        }

        // Create final undo stop - entire dictation is now one undo
        await editor.edit(() => {}, {
            undoStopBefore: false,
            undoStopAfter: true,  // End the undo group
        });

        // Clear styling
        editor.setDecorations(this.interimStyle, []);

        // Reset state
        this.reset();
    }

    /**
     * Cancel dictation and remove any interim text.
     */
    async cancel(editor: vscode.TextEditor): Promise<void> {
        if (!this.anchor || this.interimLength === 0) {
            this.reset();
            return;
        }

        // Delete the interim text
        const interimRange = new vscode.Range(
            this.anchor,
            this.anchor.translate(0, this.interimLength)
        );
        await editor.edit(eb => eb.delete(interimRange));

        // Clear styling and reset
        editor.setDecorations(this.interimStyle, []);
        this.reset();
    }

    reset(): void {
        this.anchor = null;
        this.interimLength = 0;
    }

    isActive(): boolean {
        return this.anchor !== null;
    }

    dispose(): void {
        this.interimStyle.dispose();
    }
}

/**
 * Handles text insertion into terminal.
 */
export class TerminalInserter {
    /**
     * Terminals receive only final cleaned tokens - no interim display.
     * Interim results are ignored since terminal text can't be "replaced".
